import json, glob, re, collections, sys
sys.path.insert(0, "src")
from llm_workflow_agents.data.state_convention_repair import plan_repair, apply_plan

SR = re.compile(r"\[STATE:\s*([^\]\->→]+?)\s*(?:->|→)\s*([^\]]+?)\s*\]")
def a_turns(msgs):
    r = []
    for m in msgs:
        if m.get("role") != "assistant":
            continue
        c = m.get("content") or ""
        mt = SR.search(c)
        r.append((mt.group(1) if mt else "?", mt.group(2) if mt else "?",
                  SR.sub("", c).strip()))
    return r

cnt = collections.Counter()
for f in sorted(glob.glob("data/output/sft/task_a/l*_merged_*.jsonl")):
    for line in open(f, encoding="utf-8"):
        if not line.strip():
            continue
        rec = json.loads(line)
        plan = plan_repair(rec)
        if not plan.drift_turns:
            continue
        for k, ins in enumerate(plan.inserts):
            ins.insert_id = f"x:{k}"
        ledger = {ins.insert_id: {"content": (ins.required_marker + "\nX") if ins.required_marker else "X"}
                  for ins in plan.inserts}
        out = apply_plan(rec, plan, ledger_entries=ledger or None)
        if out is None:
            cnt["conv_dropped"] += 1; continue
        B, A = a_turns(rec["messages"]), a_turns(out["messages"])
        bi = 0; amap = {}
        for a in A:
            if bi < len(B) and B[bi][2] == a[2]:
                amap[bi + 1] = a; bi += 1
        if bi != len(B):
            cnt["align_failed"] += 1; continue
        for t in plan.drift_turns:
            b, a = (B[t-1] if t-1 < len(B) else None), amap.get(t)
            if b is None or a is None:
                cnt["turn_unmapped"] += 1; continue
            cnt["drift_turns_total"] += 1
            if b[1] == a[1]:
                cnt["from_only_change"] += 1
            else:
                cnt["dest_changed"] += 1
                if a[1] == b[0]:
                    cnt["dest_pulled_back_to_own_from"] += 1
                else:
                    cnt["dest_changed_other"] += 1
print(json.dumps(dict(cnt), indent=2))
d = cnt["drift_turns_total"]
print(f"\nfrom-only:        {cnt['from_only_change']:6d}  ({100*cnt['from_only_change']/d:.1f}%)")
print(f"dest changed:     {cnt['dest_changed']:6d}  ({100*cnt['dest_changed']/d:.1f}%)")
print(f"  of which pulled back to the turn's own old `from`: "
      f"{cnt['dest_pulled_back_to_own_from']} ({100*cnt['dest_pulled_back_to_own_from']/max(cnt['dest_changed'],1):.1f}%)")
print(f"  other:                                             {cnt['dest_changed_other']}")
