        m = ins.get("required_marker") or ""
        adv = "→" in m and m.split("→")[0].split(":",1)[1].strip() != m.split("→")[1].rstrip("]").strip()
        # find the message at position_after_msg_index within the context window
        prev = None
        for w in ins.get("context_window") or []:
            if w["index"] == ins["position_after_msg_index"]:
                prev = w
        if prev is None:
            c["prev_not_in_window"] += 1; continue
        if prev["role"] != "tool":
            c[f"prev_role={prev['role']}"] += 1; continue
        try:
            payload = json.loads(prev["content"])
        except Exception:
