source .venv/bin/activate && python3 - <<'PY'
import json, glob, re, unicodedata, collections
SR = re.compile(r"\[STATE:[^\]]*\]")
led = [json.loads(l) for l in open("data/interim/task_a_remediation_ledger/accepted.jsonl") if l.strip()]
reqs = {}
for b in glob.glob("data/interim/task_a_remediation_ledger/batches/*/batch_*/batch.json"):
    for r in json.load(open(b)):
        reqs[r["insert_id"]] = r

def toks(s):
    s = SR.sub("", s or "")
    # word-ish tokens for latin, char-bigrams for Thai (no spaces)
    lat = set(re.findall(r"[A-Za-z][A-Za-z'-]{2,}", s.lower()))
    thai = "".join(c for c in s if unicodedata.name(c, "").startswith("THAI"))
    bi = {thai[i:i+3] for i in range(len(thai) - 2)}
    return lat | bi

rows = []
for e in led:
    if e["role"] != "assistant":
        continue
    rq = reqs.get(e["insert_id"])
    if not rq:
        continue
    pos = rq["position_after_msg_index"]
    nxt = next((m for m in rq["context_window"]
                if m["index"] == pos + 1 and m["role"] == "assistant"), None)
    if not nxt:
        continue
    a, b = toks(e["content"]), toks(nxt.get("content") or "")
    if len(a) < 5 or len(b) < 5:
        continue
    ov = len(a & b) / len(a)
    rows.append((ov, e["insert_id"], rq["language"]))

rows.sort(reverse=True)
print(f"assistant bridges with an assistant turn immediately after: {len(rows)}")
buckets = collections.Counter()
for ov, _, _ in rows:
    buckets[">=0.5" if ov >= .5 else ">=0.35" if ov >= .35 else ">=0.2" if ov >= .2 else "<0.2"] += 1
for k in (">=0.5", ">=0.35", ">=0.2", "<0.2"):
    n = buckets[k]
    print(f"  overlap {k:7s}: {n:4d}  ({100*n/len(rows):.1f}%)")
print(f"\nmedian overlap: {sorted(r[0] for r in rows)[len(rows)//2]:.2f}")
print("\nworst 5:")
for ov, iid, lang in rows[:5]:
    print(f"  {ov:.2f}  {iid}  {lang}")
